// План specs/estimates-sms-link.md 1.1 (кейс .qa/tests/estimates-sms-link/ES-01). Admin (компания «test») + гость, десктоп, EN.
// @writes @sms @data: создаёт смету «QA-AUTO est-sms #05c270 …» (клиент QA-SMS Client), в конце — Delete/Archive.
// SMS: запрос перехватывается до сервера (фейковый успех), телефон — вымышленный +15555550100; реальный SMS не уходит.
import { test, expect } from '../../fixtures';
import {
  QA_SMS_CLIENT, EST_0013, estimateRows, estimateSmsText, expectOnlyFakePhone, fakeSmsSent, fillEstimate,
  openNewEstimateForClient, openPublicEstimate, parseEstimateSms, removeEstimate, restoreTest, sendEstimateViaSms, startInTest,
} from './estimate-sms-helpers';

test.describe('Estimate SMS link (#05c270)', () => {
  test('New unsaved estimate → Send via SMS: saved once as Sent, SMS has EST number and a public estimate?t= link #05c270 @desktop @writes @sms @data', async ({ asUser }) => {
    test.setTimeout(180_000);
    const admin = await asUser('admin');
    await startInTest(admin);
    const smsCalls = await fakeSmsSent(admin);
    const title = `QA-AUTO est-sms #05c270 ${Date.now().toString(36)}`;
    try {
      // Шаги 1–3: новая смета без сохранения → Send → Send via SMS → Send
      await openNewEstimateForClient(admin, QA_SMS_CLIENT.name);
      await fillEstimate(admin, title, { name: 'QA-AUTO item', price: '1' });
      await sendEstimateViaSms(admin);

      // Шаг 4: текст SMS (тело перехваченного запроса)
      await expect.poll(() => smsCalls.length, { message: 'запрос отправки SMS (перехвачен)', timeout: 20_000 }).toBeGreaterThan(0);
      expect(smsCalls, 'одна отправка SMS на одно нажатие Send').toHaveLength(1);
      expectOnlyFakePhone(smsCalls);
      const text = estimateSmsText(smsCalls[0]);
      expect(text, 'в SMS нет undefined').not.toContain('undefined');
      expect(text, 'старая ссылка AssessmentDetail не используется').not.toContain('AssessmentDetail');
      const sms = parseEstimateSms(text);
      expect(sms, `формат «Techory: Hi <имя>, your estimate #EST-xxxx from test for $N is ready. View it here: <ссылка>» — получено «${text}»`).toBeTruthy();
      // «מה רצוי»: מספר ההצעה מופיע תמיד; הפנייה בשם הלקוח/איש הקשר (комментарий программиста п.3 — Contact person)
      expect(sms!.number, 'номер сметы не пустой').toMatch(/^EST-\d{4,}$/);
      expect(sms!.greeting, 'обращение — по контакту сметы').toBe(QA_SMS_CLIENT.contact);
      expect(sms!.company).toBe(EST_0013.company);
      expect(sms!.amount).toBe('$1.00');
      // «מה רצוי»: הקישור מוביל להצעה הספציפית (id אמיתי)
      expect(sms!.link, 'ссылка на публичную страницу сметы с токеном').toMatch(/^https:\/\/app\.techory\.ai\/estimate\?t=[0-9a-f-]{16,}$/i);

      // Шаг 5: в Estimates одна смета, номер из SMS, статус Sent (комментарий программиста п.2)
      const rows = await estimateRows(admin, title);
      await expect(rows, 'смета сохранена ровно один раз (без дубля)').toHaveCount(1);
      await expect(rows.first()).toContainText(sms!.number);
      await expect(rows.first()).toContainText('Sent');

      // Шаг 6: ссылка из SMS открывается без входа и показывает эту смету
      const guest = await asUser('guest');
      const token = new URL(sms!.link).searchParams.get('t');
      await openPublicEstimate(guest, token);
      await expect(guest.getByText(`Estimate #${sms!.number}`)).toBeVisible();
      await expect(guest.getByText(title)).toBeVisible();
      await expect(guest.getByText('QA-AUTO item')).toBeVisible();
      await expect(guest.getByRole('button', { name: 'Download PDF' })).toBeVisible();
    } finally {
      await removeEstimate(admin, title);
      await restoreTest(admin);
    }
    expectOnlyFakePhone(smsCalls);
  });
});
